<?php
namespace App\Services;
use App\Models\AuditLog; use App\Models\Unlock; use App\Models\UnlockStatusHistory; use App\Models\User; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class UnlockStatusService { public function transition(Unlock $unlock,string $to,?User $actor=null,?string $reason=null,array $allowed=[]): Unlock { return DB::transaction(function() use($unlock,$to,$actor,$reason,$allowed) { $locked=Unlock::lockForUpdate()->findOrFail($unlock->id); $from=$locked->status; if($from===$to)return $locked; if($allowed!==[]&&!in_array($from,$allowed,true))throw ValidationException::withMessages(['status'=>'Esta transición no está permitida.']); $locked->status=$to; $locked->status_changed_at=now(); if($to===Unlock::GOAL_REACHED)$locked->goal_reached_at??=now(); $locked->save(); UnlockStatusHistory::create(['unlock_id'=>$locked->id,'from_status'=>$from,'to_status'=>$to,'actor_user_id'=>$actor?->id,'reason'=>$reason]); if($actor){AuditLog::create(['actor_user_id'=>$actor->id,'action'=>'unlock_status_changed','subject_type'=>Unlock::class,'subject_id'=>$locked->id,'metadata'=>['from'=>$from,'to'=>$to,'reason'=>$reason]]);} return $locked; }); } public function expireMissedGoals(): int { $count=0; Unlock::whereIn('status',[Unlock::ACTIVE,Unlock::SCHEDULED])->whereNotNull('commitment_deadline')->where('commitment_deadline','<',now())->chunkById(100,function($items)use(&$count){foreach($items as $u){if($u->committedCount()<$u->minimum_commitments){$this->transition($u,Unlock::GOAL_NOT_REACHED,null,'Commitment deadline elapsed',[Unlock::ACTIVE,Unlock::SCHEDULED]);$count++;}}}); return $count; } }
